    po_ds = pick(['po_number', 'status', 'total_amount', 'eta_date'])
    purch_ds = pick(['reporting_period', 'purchase_amount', 'purchase_cases'])

    stock = {r['sku']: r for r in (stock_ds['rows'] if stock_ds else [])}
    sold = {r['sku']: r for r in (sold_ds['rows'] if sold_ds else [])}
    out = []

    cover = []
    for sku, s in sold.items():
        if sku in stock and s['units_sold']:
            days = stock[sku]['stock_on_hand'] / (s['units_sold'] / 30.0)
            cover.append((s['product_name_en'], sku, round(days, 1), stock[sku]['stock_on_hand'], s['units_sold']))
    cover.sort(key=lambda x: x[2])
    for name, sku, days, soh, us in cover:
        flag = '需立即补货' if days < 10 else ('关注补货' if days < 20 else '库存充足')
        out.append({'title': '库存可售天数', 'detail': f'{name}（{sku}）期末库存 {soh:.0f} 件，9月销量 {us:.0f} 件，按此速度仅可售约 {days} 天，{flag}。', 'evidence': {'sku': sku, 'stock_on_hand': soh, 'units_sold': us, 'days_cover': days}})

    if po_ds:
        rows = po_ds['rows']
        amt = sum(r['total_amount'] for r in rows)
        eta = sorted(r['eta_date'] for r in rows if r.get('eta_date'))
        out.append({'title': '在途采购单', 'detail': f'截至9月末仍有 {len(rows)} 张采购单未完成，合计金额 {amt:.2f}，最早预计到货 {eta[0] if eta else "未知"}，需在10月跟进到货与付款。', 'evidence': {'open_po': len(rows), 'open_amount': round(amt, 2), 'earliest_eta': eta[0] if eta else None}})

    if purch_ds:
        rows = [r for r in purch_ds['rows'] if r.get('purchase_amount')]
        if rows:
            last = rows[-1]
            prev = [r for r in rows if r['reporting_period'] != last['reporting_period']]
            avg = sum(r['purchase_amount'] for r in prev) / len(prev) if prev else 0
            out.append({'title': '采购节奏', 'detail': f'{last["reporting_period"]} 采购金额 {last["purchase_amount"]:.2f}、{last["purchase_cases"]:.0f} 箱，是前几个有采购月份均值 {avg:.2f} 的 {last["purchase_amount"]/avg:.1f} 倍，下一周期应控制补货节奏、优先消化在途与库存。', 'evidence': {'period': last['reporting_period'], 'amount': round(last['purchase_amount'], 2), 'cases': last['purchase_cases'], 'prior_avg': round(avg, 2)}})

    return out

def analyze(datasets):
    out = []
    def pick(col):
        return next((d for d in datasets if col in d.get('columns', [])), None)
    po = pick('po_number')
    if po:
        rows = po['rows']
        amt = sum(float(r['total_amount']) for r in rows)
        overdue = [r for r in rows if r.get('eta_date') and r['eta_date'] < '2026-10-01']
        out.append({'title': '未完成采购单积压', 'detail': '截至2026年9月末仍有%d张采购单未完成，合计金额%.2f元，其中%d张预计到达日已过期（最早%s）。' % (len(rows), amt, len(overdue), overdue[0]['eta_date'] if overdue else '无'), 'evidence': {'open_po': len(rows), 'open_amount': round(amt, 2), 'overdue_po': len(overdue)}})
    ev = pick('eval_rows')
    if ev:
        r = ev['rows'][0]
        out.append({'title': '采购单规则评估缺失', 'detail': '2026年9月提交的采购单在po_rule_evaluations中评估记录为%d条、规则快照%d条，无法验证MOQ与折扣档期是否合规，存在合规盲区。' % (r['eval_rows'], r['array_snapshots']), 'evidence': {'eval_rows': r['eval_rows'], 'snapshots': r['array_snapshots']}})
    tr = pick('reporting_period')
    if tr:
        rows = tr['rows']
        zero = [r['reporting_period'] for r in rows if not r.get('order_count')]
        sep = next((r for r in rows if r['reporting_period'] == '2026-09'), None)
        if sep:
            out.append({'title': '采购节奏波动', 'detail': '近六个报告期中%s无采购单，而2026-09单月采购金额%.2f元、%d箱，占近六月总额比重偏高，采购集中度风险明显。' % ('、'.join(zero) if zero else '无', float(sep['purchase_amount']), int(sep['purchase_cases'])), 'evidence': {'zero_months': len(zero), 'sep_amount': round(float(sep['purchase_amount']), 2), 'sep_cases': int(sep['purchase_cases'])}})
    st = pick('stock_on_hand')
    sl = pick('units_sold')
    if st and sl:
        sold = {r['sku']: float(r['units_sold']) for r in sl['rows']}
        for r in st['rows']:
            s = sold.get(r['sku'])
            if s and s > 0:
                days = float(r['stock_on_hand']) / (s / 30.0)
                out.append({'title': '库存可售天数', 'detail': '%s（%s）期末库存%.0f件，9月销量%.0f件，按当月速度仅可售约%.1f天，需关注补货。' % (r['product_name_en'], r['sku'], float(r['stock_on_hand']), s, days), 'evidence': {'sku': r['sku'], 'stock': float(r['stock_on_hand']), 'sold': s, 'days': round(days, 1)}})
    return out
